<script setup lang="ts">
import {onMounted,onBeforeUnmount,reactive,ref,computed} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api,message} from '../api/client'
import ProviderMappingEditor from '../components/ProviderMappingEditor.vue'
import type {ProviderDraftMapping} from '../api/provider'
import {type Provider,type ProviderType,type TestResult,healthLabels,authLabels,schedulingLabels} from '../api/provider'
const rows=ref<Provider[]>([]),types=ref<ProviderType[]>([]),page=ref(1),total=ref(0),q=ref(''),status=ref(''),providerType=ref(''),protocol=ref(''),health=ref(''),loading=ref(false),saving=ref(false),error=ref(''),dialog=ref(false),editing=ref<number|null>(null),hasKey=ref(false),testing=ref<number|null>(null),testResult=ref<TestResult|null>(null)
const advanced=ref(false)
const mappings=ref<ProviderDraftMapping[]>([]),mappingLoading=ref(false),mappingsReady=ref(false),discovering=ref(false),discovered=ref<string[]>([]),editorVersion=ref<number|null>(null)
const blank=()=>({name:'',provider_type:'openai',protocol:'openai',base_url:'https://api.openai.com/v1',api_key:'',clear_api_key:false,proxy:'',priority:0,max_concurrency:10,status:'enabled',remark:''})
const form=reactive(blank()),selectedType=computed(()=>types.value.find(t=>t.code===form.provider_type))
function typeName(code:string){return types.value.find(t=>t.code===code)?.name||code}
async function load(){loading.value=true;error.value='';try{const d=(await api.get('/admin/providers',{params:{page:page.value,q:q.value,status:status.value,provider_type:providerType.value,protocol:protocol.value,health_status:health.value}})).data.data;rows.value=d.items;total.value=d.total}catch(e){error.value=message(e)}finally{loading.value=false}}
async function open(p?:Provider&{config_version?:number}){
  editing.value=p?.id??null;editorVersion.value=p?.config_version??null;hasKey.value=p?.has_api_key||false
  Object.assign(form,blank(),p?{name:p.name,provider_type:p.provider_type,protocol:p.protocol,base_url:p.base_url,proxy:p.proxy||'',priority:p.priority,max_concurrency:p.max_concurrency,status:p.status,remark:p.remark}:{})
  mappings.value=[{logical_model:'',upstream_model:'',model_type:'text',status:'enabled'}];discovered.value=[];mappingsReady.value=!p;dialog.value=true
  if(p){mappingLoading.value=true;try{const rows=(await api.get('/admin/providers/'+p.id+'/model-mappings')).data.data;if(editing.value!==p.id)return;mappings.value=rows.length?rows.map((m:ProviderDraftMapping)=>({logical_model:m.logical_model,upstream_model:m.upstream_model,model_type:m.model_type,status:m.status})):mappings.value;mappingsReady.value=true}catch(e){ElMessage.error(message(e))}finally{mappingLoading.value=false}}
}
async function discoverDraft(){
  discovering.value=true
  try{const connection:any={name:form.name||'discovery',provider_type:form.provider_type,protocol:form.protocol,base_url:form.base_url,proxy:form.proxy||null};if(form.api_key)connection.api_key=form.api_key;if(editing.value&&!form.clear_api_key)connection.provider_id=editing.value
  discovered.value=(await api.post('/admin/providers/discover-models',connection)).data.data.models.map((m:{id:string})=>m.id);ElMessage.success('发现 '+discovered.value.length+' 个模型')}catch(e){ElMessage.error(message(e))}finally{discovering.value=false}
}
function changeType(){const t=selectedType.value;if(t){form.protocol=t.protocols[0]||'openai';form.base_url=t.base_url;discovered.value=[]}}
async function save(){if(!mappingsReady.value||mappingLoading.value)return;if(!mappings.value.length||mappings.value.some(m=>!m.logical_model.trim()||!m.upstream_model.trim())){ElMessage.error('请至少填写一条完整模型映射');return}if(new Set(mappings.value.map(m=>m.logical_model.trim())).size!==mappings.value.length){ElMessage.error('请求模型名称不能重复');return}saving.value=true;try{const payload:any={name:form.name,provider_type:form.provider_type,protocol:form.protocol,base_url:form.base_url,proxy:form.proxy||null,priority:form.priority,max_concurrency:form.max_concurrency,status:form.status,remark:form.remark};payload.model_mappings=mappings.value.map(m=>({...m,logical_model:m.logical_model.trim(),upstream_model:m.upstream_model.trim()}));if(editing.value&&editorVersion.value!==null)payload.expected_config_version=editorVersion.value;if(form.api_key)payload.api_key=form.api_key;if(editing.value){payload.clear_api_key=form.clear_api_key;await api.patch('/admin/providers/'+editing.value,payload)}else await api.post('/admin/providers',payload);dialog.value=false;form.api_key='';ElMessage.success('账号已保存');await load()}catch(e){ElMessage.error(message(e))}finally{saving.value=false}}
async function toggle(p:Provider){try{await api.patch('/admin/providers/'+p.id,{status:p.status==='enabled'?'disabled':'enabled'});await load()}catch(e){ElMessage.error(message(e))}}
async function remove(p:Provider){try{await ElMessageBox.confirm('删除后账号停止使用，历史记录保留。','删除 '+p.name,{type:'warning',confirmButtonText:'删除',cancelButtonText:'取消'});await api.delete('/admin/providers/'+p.id);await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(message(e))}}
async function test(p:Provider){testing.value=p.id;try{testResult.value=(await api.post('/admin/providers/'+p.id+'/test')).data.data;await load()}catch(e){ElMessage.error(message(e))}finally{testing.value=null}}
onMounted(async()=>{try{types.value=(await api.get('/admin/providers/types')).data.data}catch(e){error.value=message(e)}await load()});onBeforeUnmount(()=>{form.api_key=''})
</script>
<template><div><PageHeader title="模型供应商" description="配置上游模型服务，检查连接状态与鉴权结果。"><el-button type="primary" @click="open()">新增账号</el-button></PageHeader><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="panel"><div class="toolbar"><el-input v-model="q" placeholder="搜索账号名称" clearable style="width:240px" @keyup.enter="page=1;load()"/><el-select v-model="status" clearable placeholder="全部状态" style="width:140px"><el-option label="启用" value="enabled"/><el-option label="禁用" value="disabled"/></el-select><el-select v-model="providerType" clearable placeholder="全部供应商" style="width:150px"><el-option v-for="t in types" :key="t.code" :value="t.code" :label="t.name"/></el-select><el-select v-if="advanced" v-model="protocol" clearable placeholder="全部协议" style="width:140px"><el-option label="OpenAI" value="openai"/><el-option label="Anthropic" value="anthropic"/><el-option label="Ollama" value="ollama"/></el-select><el-select v-if="advanced" v-model="health" clearable placeholder="全部健康状态" style="width:155px"><el-option label="未测试" value="unknown"/><el-option label="连接正常" value="healthy"/><el-option label="连接异常" value="unhealthy"/></el-select><el-button @click="page=1;load()">查询</el-button><el-button @click="advanced=!advanced">{{advanced?'收起筛选':'更多筛选'}}</el-button></div><el-table :data="rows" v-loading="loading" empty-text="暂无账号，请添加实际模型服务"><el-table-column label="账号" min-width="160"><template #default="s"><router-link :to="'/admin/providers/'+s.row.id" style="color:var(--el-color-primary)">{{s.row.name}}</router-link></template></el-table-column><el-table-column label="供应商 / 协议" min-width="180"><template #default="s">{{typeName(s.row.provider_type)}}<div class="muted">{{s.row.protocol}}</div></template></el-table-column><el-table-column label="状态" width="85"><template #default="s"><el-tag :type="s.row.status==='enabled'?'success':'info'">{{s.row.status==='enabled'?'启用':'禁用'}}</el-tag></template></el-table-column><el-table-column label="健康状态" width="115"><template #default="s"><el-tag :type="s.row.health_status==='healthy'?'success':s.row.health_status==='unhealthy'?'danger':'info'">{{healthLabels[s.row.health_status]}}</el-tag></template></el-table-column><el-table-column label="调度状态" width="110"><template #default="s"><el-tag :type="s.row.scheduling_state==='Available'?'success':s.row.scheduling_state==='Cooling'?'warning':s.row.scheduling_state==='Unavailable'?'danger':'info'">{{schedulingLabels[s.row.scheduling_state]}}</el-tag></template></el-table-column><el-table-column label="当前 / 最大并发" width="155"><template #default="s">{{s.row.current_concurrency??'未知'}} / {{s.row.max_concurrency}}<el-progress v-if="s.row.current_concurrency!==null" :percentage="Math.min(100,s.row.current_concurrency/s.row.max_concurrency*100)" :show-text="false" :stroke-width="4"/></template></el-table-column><el-table-column prop="priority" label="优先级" width="85"/><el-table-column label="最近延迟" width="110"><template #default="s">{{s.row.last_latency_ms==null?'—':s.row.last_latency_ms+' ms'}}</template></el-table-column><el-table-column label="Key" width="90"><template #default="s">{{s.row.has_api_key?'已配置':'未配置'}}</template></el-table-column><el-table-column label="操作" width="235" fixed="right"><template #default="s"><el-button link type="primary" @click="open(s.row)">编辑</el-button><el-button link :disabled="s.row.status!=='enabled'||testing!==null" :loading="testing===s.row.id" @click="test(s.row)">连接测试</el-button><el-button link @click="toggle(s.row)">{{s.row.status==='enabled'?'禁用':'启用'}}</el-button><el-button link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column><template #empty><EmptyState title="暂无账号，请添加实际模型服务" description="检查筛选条件、时间范围或相关配置后重试。"/></template></el-table><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total, prev, pager, next" style="margin-top:24px" @current-change="load"/></div><el-drawer v-model="dialog" :title="editing?'编辑账号':'新增账号'" size="860px" @closed="form.api_key=''"><el-form label-width="115px"><el-form-item label="账号名称"><el-input v-model="form.name" maxlength="80"/></el-form-item><el-form-item label="供应商"><el-select v-model="form.provider_type" @change="changeType"><el-option v-for="t in types" :key="t.code" :value="t.code" :label="t.name"/></el-select></el-form-item><el-form-item v-if="selectedType?.description" label="接入说明"><div><p style="margin:0 0 8px;line-height:1.6">{{selectedType.description}}</p><a :href="selectedType.docs_url" target="_blank" rel="noopener noreferrer" style="color:var(--el-color-primary)">查看官方文档</a></div></el-form-item><el-form-item label="协议"><el-select v-model="form.protocol"><el-option v-for="p in selectedType?.protocols||[]" :key="p" :value="p" :label="p"/></el-select></el-form-item><el-form-item label="Base URL"><el-input v-model="form.base_url" placeholder="包含API版本路径，例如 https://api.openai.com/v1" maxlength="2048"/></el-form-item><el-form-item label="API Key"><el-input v-model="form.api_key" type="password" autocomplete="new-password" :placeholder="editing?'留空保留原Key':selectedType?.key_required?'请填写上游Key':'可选，本地服务可不配置'" maxlength="4096"/></el-form-item><el-form-item v-if="editing&&hasKey" label="已有 Key"><span>已配置，完整密钥不可查看</span><el-checkbox v-model="form.clear_api_key" style="margin-left:15px">清除原Key</el-checkbox></el-form-item><div v-loading="mappingLoading"><ProviderMappingEditor v-model="mappings" :models="discovered" :discovering="discovering" @discover="discoverDraft"/></div><el-form-item label="HTTP代理"><el-input v-model="form.proxy" placeholder="可选：http://代理地址:端口" maxlength="2048"/></el-form-item><el-form-item label="优先级"><el-input-number v-model="form.priority" :min="0" :max="100000" :precision="0"/><span class="muted" style="margin-left:12px">数值越小越优先；相同优先级按负载调度。</span></el-form-item><el-form-item label="最大并发"><el-input-number v-model="form.max_concurrency" :min="1" :max="100000" :precision="0"/></el-form-item><el-form-item label="状态"><el-select v-model="form.status"><el-option label="启用" value="enabled"/><el-option label="禁用" value="disabled"/></el-select></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea" maxlength="2000"/></el-form-item><p class="muted">连接测试读取模型列表，检查网络和鉴权。它不会发起生成请求。</p></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" :disabled="mappingLoading||!mappingsReady" @click="save">保存</el-button></template></el-drawer><el-dialog :model-value="!!testResult" title="连接测试结果" width="580px" @close="testResult=null"><template v-if="testResult"><el-alert :title="testResult.message" :type="testResult.success?'success':'error'" :closable="false"/><el-descriptions :column="2" border style="margin-top:20px"><el-descriptions-item label="网络">{{testResult.network_connected?'已连接':'未确认连接'}}</el-descriptions-item><el-descriptions-item label="鉴权">{{authLabels[testResult.authentication]}}</el-descriptions-item><el-descriptions-item label="HTTP状态">{{testResult.http_status??'无响应'}}</el-descriptions-item><el-descriptions-item label="响应时间">{{testResult.latency_ms}} ms</el-descriptions-item><el-descriptions-item label="返回模型数">{{testResult.model_count??'未取得'}}</el-descriptions-item><el-descriptions-item label="错误代码">{{testResult.error_code||'无'}}</el-descriptions-item></el-descriptions></template></el-dialog></div></template>


